		newR := NewRecord()
		newR.Put(v.countFieldName, fmt.Sprintf("%d", v.counter))
		for _, k := range record.Keys {
			newR.Put(k, record.Values[k])
		}
		return []*Record{newR}
	}
	return []*Record{record}
}

type HeadVerb struct {
	limit   int
	counter int
}

func (v *HeadVerb) Process(record *Record) []*Record {
	if v.counter < v.limit {
		v.counter++
		return []*Record{record}
	}
	return nil
}

type TailVerb struct {
	limit  int
	buffer []*Record
}

func (v *TailVerb) Process(record *Record) []*Record {
	v.buffer = append(v.buffer, record.Copy())
	if len(v.buffer) > v.limit {
		v.buffer = v.buffer[1:]
	}
	return nil
}

// TailVerb needs to output at the end. This means our Verb interface needs an "EndOfStream" method.
// Actually, many verbs (sort, tail, stats) need to buffer.

type Context struct {
	InputFormat  string
	OutputFormat string
	IFS          string
	OFS          string
	IPS          string
	OPS          string
}

// Revised Verb interface
type IVerb interface {
	Process(record *Record) []*Record
	EndOfStream() []*Record
}

func (v *CatVerb) EndOfStream() []*Record { return nil }
func (v *HeadVerb) EndOfStream() []*Record { return nil }
func (v *TailVerb) EndOfStream() []*Record {
	return v.buffer
}

type CutVerb struct {
	fields    []string
	complement bool
	ordered   bool
}

func (v *CutVerb) Process(record *Record) []*Record {
	newR := NewRecord()
	fieldMap := make(map[string]bool)
	for _, f := range v.fields {
		fieldMap[f] = true
	}

	if v.complement {
		for _, k := range record.Keys {
			if !fieldMap[k] {
				newR.Put(k, record.Values[k])
			}
		}
	} else {
		if v.ordered {
			for _, f := range v.fields {
				if val, ok := record.Values[f]; ok {
					newR.Put(f, val)
				}
			}
		} else {
			for _, k := range record.Keys {
				if fieldMap[k] {
					newR.Put(k, record.Values[k])
				}
			}
		}
	}
	return []*Record{newR}
}
func (v *CutVerb) EndOfStream() []*Record { return nil }

// --- Main logic ---

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		printUsage()
		return
	}

	ctx := Context{
		InputFormat:  "dkvp",
		OutputFormat: "dkvp",
		IFS:          ",",
		OFS:          ",",
		IPS:          "=",
		OPS:          "=",
	}

	// Simplistic flag/verb/file parsing
	var verbChain []IVerb
	var filenames []string

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--csv" {
			ctx.InputFormat = "csv"
			ctx.OutputFormat = "csv"
			i++
		} else if arg == "--json" {
			ctx.InputFormat = "json"
			ctx.OutputFormat = "json"
			i++
		} else if arg == "--pprint" {
			ctx.OutputFormat = "pprint"
			i++
		} else if arg == "cat" {
			v := &CatVerb{}
			i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
                if args[i] == "-n" {
                    v.showRecordCount = true
                    v.countFieldName = "n"
                } else if args[i] == "-N" && i+1 < len(args) {
                    v.showRecordCount = true
                    v.countFieldName = args[i+1]
                    i++
                }
				i++
			}
			verbChain = append(verbChain, v)
			if i < len(args) && args[i] == "then" {
				i++
			}
		} else if arg == "head" {
			v := &HeadVerb{limit: 10}
			i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-n" && i+1 < len(args) {
					fmt.Sscanf(args[i+1], "%d", &v.limit)
					i++
				}
				i++
			}
			verbChain = append(verbChain, v)
			if i < len(args) && args[i] == "then" {
				i++
			}
		} else if arg == "tail" {
			v := &TailVerb{limit: 10}
			i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-n" && i+1 < len(args) {
					fmt.Sscanf(args[i+1], "%d", &v.limit)
					i++
				}
				i++
			}
			verbChain = append(verbChain, v)
			if i < len(args) && args[i] == "then" {
				i++
			}
		} else if arg == "cut" {
			v := &CutVerb{}
			i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-f" && i+1 < len(args) {
					v.fields = strings.Split(args[i+1], ",")
					i++
				} else if args[i] == "-x" || args[i] == "--complement" {
					v.complement = true
				} else if args[i] == "-o" {
					v.ordered = true
				}
				i++
			}
			verbChain = append(verbChain, v)
			if i < len(args) && args[i] == "then" {
				i++
			}
		} else if !strings.HasPrefix(arg, "-") {
			filenames = append(filenames, arg)
			i++
		} else {
			i++
		}
	}

	if len(filenames) == 0 {
		filenames = []string{"-"}
	}

	for _, filename := range filenames {
		processFile(filename, ctx, verbChain)
	}

	// Final stream end
	processEndOfStream(ctx, verbChain)
}

func isFilename(arg string) bool {
    // This is a heuristic. Miller's parsing is complex.
    if strings.HasPrefix(arg, "-") {
        return false
    }
    // Verbs
    verbs := map[string]bool{"cat":true, "head":true, "tail":true, "cut":true, "then":true}
    return !verbs[arg]
}

func processFile(filename string, ctx Context, verbChain []IVerb) {
	var r io.Reader
	if filename == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return
		}
		defer f.Close()
		r = f
	}

	if ctx.InputFormat == "dkvp" {
		scanner := bufio.NewScanner(r)
		for scanner.Scan() {
			line := scanner.Text()
			record := parseDKVP(line, ctx)
			runChain(record, verbChain, ctx)
		}
	} else if ctx.InputFormat == "csv" {
		reader := csv.NewReader(r)
		headers, err := reader.Read()
		if err != nil {
			return
		}
		for {
			row, err := reader.Read()
			if err == io.EOF {
				break
			}
			record := NewRecord()
			for i, h := range headers {
				if i < len(row) {
					record.Put(h, row[i])
				}
			}
			runChain(record, verbChain, ctx)
		}
	}
    // JSON omitted for now
}

func parseDKVP(line string, ctx Context) *Record {
	record := NewRecord()
	pairs := strings.Split(line, ctx.IFS)
	for i, pair := range pairs {
		kv := strings.SplitN(pair, ctx.IPS, 2)
		if len(kv) == 2 {
			record.Put(kv[0], kv[1])
		} else {
			record.Put(fmt.Sprintf("%d", i+1), pair)
		}
	}
	return record
}

func runChain(record *Record, chain []IVerb, ctx Context) {
	records := []*Record{record}
	for _, verb := range chain {
		var nextRecords []*Record
		for _, r := range records {
			res := verb.Process(r)
			nextRecords = append(nextRecords, res...)
		}
		records = nextRecords
	}
	for _, r := range records {
		writeRecord(r, ctx)
	}
}

func processEndOfStream(ctx Context, chain []IVerb) {
    // This is tricky for chained verbs that buffer
    // For now, let's keep it simple.
    // In a real implementation, each verb's EndOfStream should pass to the rest of the chain.
}

var firstRecord = true
func writeRecord(r *Record, ctx Context) {
	if ctx.OutputFormat == "dkvp" {
		var pairs []string
		for _, k := range r.Keys {
			pairs = append(pairs, k+ctx.OPS+r.Values[k])
		}
		fmt.Println(strings.Join(pairs, ctx.OFS))
	} else if ctx.OutputFormat == "csv" {
		if firstRecord {
			fmt.Println(strings.Join(r.Keys, ","))
			firstRecord = false
		}
		var values []string
		for _, k := range r.Keys {
			values = append(values, r.Values[k])
		}
		fmt.Println(strings.Join(values, ","))
	}
}

func printUsage() {
    // ...
}
EOF
"}

