		var p []string
		for _, k := range firstHeader { p = append(p, r.Values[k]) }
		fmt.Println(strings.Join(p, ","))
	} else if oformat == "json" {
		collectedRecords = append(collectedRecords, r.Copy())
	} else if oformat == "pprint" {
		var p []string
		for _, k := range r.Keys { p = append(p, r.Values[k]) }
		fmt.Println(strings.Join(p, " "))
	}
}
