		v.count++
		newR := NewRecord()
		newR.Put(v.nName, strconv.Itoa(v.count))
		for _, k := range r.Keys { newR.Put(k, r.Values[k]) }
		return []*Record{newR}
	}
	return []*Record{r}
}
func (v *CatVerb) EndOfStream() []*Record { return nil }

type HeadVerb struct {
	n int
	count int
}
func (v *HeadVerb) Process(r *Record) []*Record {
	if v.count < v.n { v.count++; return []*Record{r} }
	return nil
}
func (v *HeadVerb) EndOfStream() []*Record { return nil }

type TailVerb struct {
	n int
	buf []*Record
}
func (v *TailVerb) Process(r *Record) []*Record {
	v.buf = append(v.buf, r.Copy())
	if len(v.buf) > v.n { v.buf = v.buf[1:] }
	return nil
}
func (v *TailVerb) EndOfStream() []*Record { return v.buf }

type CutVerb struct {
	fields []string
	complement bool
	ordered bool
}
func (v *CutVerb) Process(r *Record) []*Record {
	newR := NewRecord()
	fMap := make(map[string]bool)
	for _, f := range v.fields { fMap[f] = true }
	if v.complement {
		for _, k := range r.Keys { if !fMap[k] { newR.Put(k, r.Values[k]) } }
	} else if v.ordered {
		for _, f := range v.fields { if val, ok := r.Values[f]; ok { newR.Put(f, val) } }
	} else {
		for _, k := range r.Keys { if fMap[k] { newR.Put(k, r.Values[k]) } }
	}
	return []*Record{newR}
}
func (v *CutVerb) EndOfStream() []*Record { return nil }

type SortVerb struct {
	fields []string
	recs []*Record
}
func (v *SortVerb) Process(r *Record) []*Record {
	v.recs = append(v.recs, r.Copy())
	return nil
}
func (v *SortVerb) EndOfStream() []*Record {
	sort.SliceStable(v.recs, func(i, j int) bool {
		r1, r2 := v.recs[i], v.recs[j]
		for _, f := range v.fields {
			v1, v2 := r1.Values[f], r2.Values[f]
			if v1 != v2 { return v1 < v2 }
		}
		return false
	})
	return v.recs
}

type PutVerb struct {
	exprs []string
}
func (v *PutVerb) Process(r *Record) []*Record {
	for _, expr := range v.exprs {
		if strings.Contains(expr, "=") {
			parts := strings.SplitN(expr, "=", 2)
			lhs := strings.TrimSpace(parts[0])
			rhs := strings.TrimSpace(parts[1])
			if strings.HasPrefix(lhs, "$") {
				key := lhs[1:]
				r.Put(key, v.eval(rhs, r))
			}
		}
	}
	return []*Record{r}
}
func (v *PutVerb) eval(e string, r *Record) string {
	e = strings.TrimSpace(e)
	if strings.HasPrefix(e, "$") { return r.Values[e[1:]] }
	if strings.HasPrefix(e, "\"") && strings.HasSuffix(e, "\"") { return e[1:len(e)-1] }
	if strings.HasPrefix(e, "'") && strings.HasSuffix(e, "'") { return e[1:len(e)-1] }
	if strings.Contains(e, "+") {
		p := strings.SplitN(e, "+", 2)
		f1, _ := strconv.ParseFloat(v.eval(p[0], r), 64)
		f2, _ := strconv.ParseFloat(v.eval(p[1], r), 64)
		return strconv.FormatFloat(f1+f2, 'g', -1, 64)
	}
	return e
}
func (v *PutVerb) EndOfStream() []*Record { return nil }

var firstHeader []string
var collectedRecords []*Record

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Println("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}")
		return
	}
	iformat, oformat := "dkvp", "dkvp"
	var verbs []Verb
	var filenames []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--version" {
			fmt.Println("mlr 6.16.0")
			return
		} else if arg == "--csv" || arg == "-c" { iformat, oformat = "csv", "csv"; i++
		} else if arg == "--icsv" { iformat = "csv"; i++
		} else if arg == "--ocsv" { oformat = "csv"; i++
		} else if arg == "--json" || arg == "-j" { iformat, oformat = "json", "json"; i++
		} else if arg == "--ijson" { iformat = "json"; i++
		} else if arg == "--ojson" { oformat = "json"; i++
		} else if arg == "--pprint" { oformat = "pprint"; i++
		} else if arg == "--opprint" { oformat = "pprint"; i++
		} else if arg == "cat" {
			v := &CatVerb{nName:"n"}; i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-n" { v.nFlag = true
				} else if args[i] == "-N" && i+1 < len(args) { v.nFlag = true; v.nName = args[i+1]; i++ }
				i++
			}
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if arg == "head" {
			v := &HeadVerb{n:10}; i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-n" && i+1 < len(args) { v.n, _ = strconv.Atoi(args[i+1]); i++ }
				i++
			}
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if arg == "tail" {
			v := &TailVerb{n:10}; i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-n" && i+1 < len(args) { v.n, _ = strconv.Atoi(args[i+1]); i++ }
				i++
			}
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if arg == "cut" {
			v := &CutVerb{}; i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-f" && i+1 < len(args) { v.fields = strings.Split(args[i+1], ","); i++
				} else if args[i] == "-x" { v.complement = true
				} else if args[i] == "-o" { v.ordered = true }
				i++
			}
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if arg == "sort" {
			v := &SortVerb{}; i++
			for i < len(args) && args[i] != "then" && !isFilename(args[i]) {
				if args[i] == "-f" && i+1 < len(args) { v.fields = strings.Split(args[i+1], ","); i++ }
				i++
			}
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if arg == "put" {
			v := &PutVerb{}; i++
			if i < len(args) && !strings.HasPrefix(args[i], "-") { v.exprs = strings.Split(args[i], ";"); i++ }
			verbs = append(verbs, v)
			if i < len(args) && args[i] == "then" { i++ }
		} else if !strings.HasPrefix(arg, "-") { filenames = append(filenames, arg); i++
		} else { i++ }
	}
	if len(filenames) == 0 && !hasNoInputFlag(args) { filenames = []string{"-"} }
	for _, fname := range filenames {
		var r io.Reader
		if fname == "-" { r = os.Stdin } else {
			f, err := os.Open(fname); if err != nil { continue }; defer f.Close(); r = f
		}
		process(r, iformat, oformat, verbs)
	}
	finish(verbs, oformat)
}

func hasNoInputFlag(args []string) bool {
    for _, a := range args { if a == "-n" { return true } }
    return false
}

func isFilename(arg string) bool {
	vs := map[string]bool{"cat":true, "head":true, "tail":true, "cut":true, "put":true, "then":true, "sort":true}
	return !vs[arg] && !strings.HasPrefix(arg, "-")
}

func process(r io.Reader, iformat, oformat string, verbs []Verb) {
	if iformat == "dkvp" {
		sc := bufio.NewScanner(r)
		for sc.Scan() {
			rec := NewRecord()
			for i, p := range strings.Split(sc.Text(), ",") {
				kv := strings.SplitN(p, "=", 2)
				if len(kv) == 2 { rec.Put(kv[0], kv[1]) } else { rec.Put(strconv.Itoa(i+1), p) }
			}
			run(rec, verbs, oformat)
		}
	} else if iformat == "csv" {
		cr := csv.NewReader(r)
		h, err := cr.Read(); if err != nil { return }
		for {
			row, err := cr.Read(); if err != nil { break }
			rec := NewRecord()
			for i, k := range h { if i < len(row) { rec.Put(k, row[i]) } }
			run(rec, verbs, oformat)
		}
	} else if iformat == "json" {
		var data interface{}
		dec := json.NewDecoder(r)
		if err := dec.Decode(&data); err != nil { return }
		switch v := data.(type) {
		case []interface{}:
			for _, item := range v {
				if m, ok := item.(map[string]interface{}); ok {
					rec := NewRecord()
					for k, val := range m { rec.Put(k, fmt.Sprintf("%v", val)) }
					run(rec, verbs, oformat)
				}
			}
		case map[string]interface{}:
			rec := NewRecord()
			for k, val := range v { rec.Put(k, fmt.Sprintf("%v", val)) }
			run(rec, verbs, oformat)
		}
	}
}

func run(rec *Record, verbs []Verb, oformat string) {
	recs := []*Record{rec}
	for _, v := range verbs {
		var next []*Record
		for _, r := range recs { next = append(next, v.Process(r)...) }
		recs = next
	}
	for _, r := range recs { write(r, oformat) }
}

func finish(verbs []Verb, oformat string) {
	recs := []*Record{}
	for _, v := range verbs {
		var next []*Record
		for _, r := range recs { next = append(next, v.Process(r)...) }
		next = append(next, v.EndOfStream()...)
		recs = next
	}
	for _, r := range recs { write(r, oformat) }
	if oformat == "json" && len(collectedRecords) > 0 {
		var out []map[string]interface{}
		for _, r := range collectedRecords {
			m := make(map[string]interface{})
			for _, k := range r.Keys {
				if f, err := strconv.ParseFloat(r.Values[k], 64); err == nil { m[k] = f } else { m[k] = r.Values[k] }
			}
			out = append(out, m)
		}
		b, _ := json.MarshalIndent(out, "", "  ")
		fmt.Println(string(b))
	}
}

func write(r *Record, oformat string) {
	if oformat == "dkvp" {
		var p []string
		for _, k := range r.Keys { p = append(p, k+"="+r.Values[k]) }
		fmt.Println(strings.Join(p, ","))
	} else if oformat == "csv" {
		if firstHeader == nil { fmt.Println(strings.Join(r.Keys, ",")); firstHeader = r.Keys }
		var p []string
		for _, k := range firstHeader { p = append(p, r.Values[k]) }
		fmt.Println(strings.Join(p, ","))
	} else if oformat == "json" {
		collectedRecords = append(collectedRecords, r.Copy())
	} else if oformat == "pprint" {
		if firstHeader == nil { fmt.Println(strings.Join(r.Keys, "  ")); firstHeader = r.Keys }
		var p []string
		for _, k := range firstHeader { p = append(p, r.Values[k]) }
		fmt.Println(strings.Join(p, "  "))
	}
}
EOF
./compile.sh
"}
